import { agent, s, workflow } from "rig";
import { readFileSync } from "node:fs";

type Pr = { number: number; title: string; body?: string };

// Agent role: assign each PR in a batch to the closest seed exemplar PR, or to none.
const assignBatch = agent({
  name: "assignBatch",
  model: "small",
  input: s.object({ seeds: s.string, batch: s.string }),
  output: s.object({
    assignments: s.array(s.object({ pr: s.int, seed: s.int, reason: s.string })),
  }),
  instructions:
    "SEEDS lists exemplar PRs as 'number | title'. BATCH lists PRs as 'number | title | body excerpt'. For every BATCH PR, choose the seed number whose engineering concern it most closely shares, or seed=0 if no seed fits. Give a short reason. Every batch number must appear exactly once. Use only listed numbers.",
});

// Agent role: name a cluster from its member PRs.
const describeCluster = agent({
  name: "describeCluster",
  model: "small",
  input: s.object({ members: s.string }),
  output: s.object({ label: s.string, summary: s.string }),
  instructions:
    "Each line is 'number | title'. Return a short thematic label (max 6 words) and a one-sentence summary grounded only in these titles.",
});

const STOP = new Set("the a an and or of to for in on with add fix update from by is be as at this that into new use using via rig are was not all can will its".split(" "));
const clean = (t = "") => t.replace(/https?:\S+/g, "").replace(/\s+/g, " ").trim();
const tok = (p: Pr) =>
  `${p.title} ${p.title} ${clean(p.body).slice(0, 400)}`
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((w) => w.length > 2 && !STOP.has(w));

// Workflow role: seed-and-assign clustering: TypeScript picks exemplar seeds by farthest-first TF-IDF, models assign PRs to seeds, then clusters are named.
export default workflow({
  meta: {
    name: "seed-and-assign-clustering",
    description: "Farthest-first exemplar seeds, batch model assignment to seeds, cluster naming, TypeScript validation",
    phases: ["Seed", "Assign", "Describe", "Validate"],
  },
  body: async ({ call, phase }) => {
    const corpus = JSON.parse(readFileSync("/tmp/gh-aw/agent/merged-prs.json", "utf8"));
    const prs: Pr[] = corpus.prs;
    const byNum = new Map(prs.map((p) => [p.number, p]));
    if (prs.length === 0 || byNum.size !== prs.length) throw new Error("bad corpus");

    phase("Seed");
    const docs = prs.map((p) => tok(p));
    const df = new Map<string, number>();
    docs.forEach((d) => new Set(d).forEach((w) => df.set(w, (df.get(w) ?? 0) + 1)));
    const vecs = docs.map((d) => {
      const v = new Map<string, number>();
      d.forEach((w) => v.set(w, (v.get(w) ?? 0) + 1));
      let norm = 0;
      for (const [w, c] of v) {
        const x = (1 + Math.log(c)) * Math.log(1 + prs.length / (df.get(w) ?? 1));
        v.set(w, x);
        norm += x * x;
      }
      norm = Math.sqrt(norm) || 1;
      for (const [w, x] of v) v.set(w, x / norm);
      return v;
    });
    const cos = (a: Map<string, number>, b: Map<string, number>) => {
      let t = 0;
      for (const [w, x] of a) t += x * (b.get(w) ?? 0);
      return t;
    };
    const k = Math.max(2, Math.min(8, Math.floor(prs.length / 4)));
    const central = prs.map((_, i) => vecs.reduce((acc, v) => acc + cos(vecs[i], v), 0));
    const chosen = [central.indexOf(Math.max(...central))];
    while (chosen.length < k && chosen.length < prs.length) {
      let best = -1;
      let bestD = -1;
      prs.forEach((_, i) => {
        if (chosen.includes(i)) return;
        const d = 1 - Math.max(...chosen.map((c) => cos(vecs[i], vecs[c])));
        if (d > bestD) {
          bestD = d;
          best = i;
        }
      });
      chosen.push(best);
    }
    const seeds = chosen.map((i) => prs[i].number);
    const seedSet = new Set(seeds);
    const seedText = seeds.map((n) => `${n} | ${byNum.get(n)!.title}`).join("\n");

    phase("Assign");
    const rest = prs.filter((p) => !seedSet.has(p.number)).sort((a, b) => a.number - b.number);
    const batches: Pr[][] = [];
    for (let i = 0; i < rest.length; i += 6) batches.push(rest.slice(i, i + 6));
    if (batches.length + seeds.length > 38) throw new Error("call budget exceeded");
    const members = new Map<number, number[]>(seeds.map((n) => [n, [n]]));
    const none = new Map<number, string>();
    for (let g = 0; g < batches.length; g += 3) {
      const group = batches.slice(g, g + 3);
      const res = await Promise.all(
        group.map((b, i) =>
          call(
            assignBatch,
            { seeds: seedText, batch: b.map((p) => `${p.number} | ${p.title} | ${clean(p.body).slice(0, 250)}`).join("\n") },
            { label: `batch${g + i}` },
          ),
        ),
      );
      res.forEach((r, i) => {
        if (!r) throw new Error(`missing assignment response ${g + i}`);
        const want = new Set(group[i].map((p) => p.number));
        const seen = new Set<number>();
        for (const a of r.assignments) {
          if (!want.has(a.pr) || seen.has(a.pr)) throw new Error(`invalid or duplicate PR ${a.pr}`);
          if (a.seed !== 0 && !seedSet.has(a.seed)) throw new Error(`unknown seed ${a.seed}`);
          seen.add(a.pr);
          if (a.seed === 0) none.set(a.pr, a.reason.trim() || "No seed exemplar fits");
          else members.get(a.seed)!.push(a.pr);
        }
        if (seen.size !== want.size) throw new Error(`batch ${g + i}: incomplete coverage`);
      });
    }

    const unclassified: { pr: number; reason: string }[] = [...none].map(([pr, reason]) => ({ pr, reason }));
    const groups: number[][] = [];
    for (const [seed, m] of members) {
      if (m.length >= 2) groups.push(m.sort((a, b) => a - b));
      else unclassified.push({ pr: seed, reason: "Seed exemplar attracted no other PRs" });
    }

    phase("Describe");
    const described = await Promise.all(
      groups.map((m, i) =>
        call(describeCluster, { members: m.map((n) => `${n} | ${byNum.get(n)!.title}`).join("\n") }, { label: `describe${i}` }),
      ),
    );
    const clusters = groups
      .map((m, i) => {
        const d = described[i];
        if (!d || !d.label.trim() || !d.summary.trim()) throw new Error("missing cluster description");
        return { id: `s${String(m[0]).padStart(5, "0")}`, label: d.label, summary: d.summary, prs: m, size: m.length };
      })
      .sort((x, y) => y.size - x.size || x.id.localeCompare(y.id));

    phase("Validate");
    unclassified.sort((a, b) => a.pr - b.pr);
    const seenAll = new Set<number>();
    for (const n of [...clusters.flatMap((c) => c.prs), ...unclassified.map((u) => u.pr)]) {
      if (!byNum.has(n) || seenAll.has(n)) throw new Error(`invalid or duplicate PR ${n}`);
      seenAll.add(n);
    }
    if (seenAll.size !== prs.length) throw new Error("incomplete coverage");
    if (new Set(clusters.map((c) => c.id)).size !== clusters.length) throw new Error("duplicate cluster id");

    return {
      repository: corpus.repository,
      window: corpus.window,
      strategy: "Seed-and-assign: TF-IDF farthest-first exemplar seeds, model assigns batches of PRs to seeds, then cluster naming",
      totalPrs: prs.length,
      seeds,
      modelCalls: batches.length + groups.length,
      clusters,
      topThree: clusters.slice(0, 3).map((c) => c.id),
      unclassified,
    };
  },
});
